def mean_absolute_deviation(numbers: List[float]) -> float:
    if len(numbers) == 0:
        return 0.0
    centerpoint = sum(numbers) / len(numbers)
    deviations = [abs(x - centerpoint) for x in numbers]
    return sum(deviations) / len(numbers)

