def max_product(num_str, N, K):
    if K == 0:
        return int(num_str)
    if N == 1:
        return 1
    max_product_left = max_product(num_str[:N//2], N//2, K-1)
    max_product_right = max_product(num_str[N//2:], N//2, K-1)
    max_product_middle = int(num_str[N//2:]) * max_product_left * max_product_right
    return max(max_product_left, max_product_right, max_product_middle)

