def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ""
        if coeff != 1 or i == 0:
            term += str(abs(coeff))
        if i > 0:
            term += "x^" + str(i)
        if coeff < 0:
            term = "-" + term
        if result != "":
            result += "+"
        result += term
    return result

