def catalan_number(n):
    """
    Calculate the nth Catalan number.

    The function computes the nth Catalan number using dynamic programming. Catalan numbers are a sequence of natural numbers that have many applications in combinatorial mathematics, including the counting of certain types of lattice paths, the number of expressions containing n pairs of parentheses which are correctly matched, the number of different ways n+1 factors can be completely parenthesized, and more.

    Args:
        n (int): The position in the Catalan number sequence to compute (must be non-negative).

    Returns:
        int: The nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    else:
        return sum(catalan_number(i) * catalan_number(n-1-i) for i in range(n))

